from solution import multiply
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_unit(n: int) -> int:
    return abs(n) % 10


def ref_multiply(a: int, b: int) -> int:
    return ref_unit(a) * ref_unit(b)


def test_spec_example_148_412():
    assert multiply(148, 412) == 16


def test_spec_example_19_28():
    assert multiply(19, 28) == 72


def test_spec_example_2020_1851():
    assert multiply(2020, 1851) == 0


def test_spec_example_14_neg15():
    assert multiply(14, -15) == 20


def test_negative_unit_digit_ignores_sign():
    # unit digit of -19 is 9, so 9*8=72
    assert multiply(-19, 28) == 72


def test_negative_both_operands():
    # 4*5=20 ; Python's -14 % 10 == 6 would give 30 if buggy
    assert multiply(-14, -15) == 20


def test_negative_with_non_symmetric_digit():
    # -148 unit digit is 8, 412 unit digit is 2 -> 16
    assert multiply(-148, 412) == 16
    assert multiply(148, -412) == 16
    assert multiply(-148, -412) == 16


def test_single_digit_product_equals_arithmetic_product():
    for a in range(10):
        for b in range(10):
            assert multiply(a, b) == a * b


def test_trailing_zero_gives_zero():
    assert multiply(10, 123) == 0
    assert multiply(-10, 123) == 0
    assert multiply(0, 0) == 0
    assert multiply(0, -7) == 0
    assert multiply(2020, 5) == 0


@given(
    a=st.integers(min_value=-10000, max_value=10000),
    b=st.integers(min_value=-10000, max_value=10000),
)
def test_equivalence_to_abs_mod_reference_model(a, b):
    assert multiply(a, b) == ref_multiply(a, b)


@given(a=st.integers(min_value=-10000, max_value=10000),
       b=st.integers(min_value=-10000, max_value=10000))
def test_sign_invariance(a, b):
    # unit digits ignore sign, so flipping signs must not change result
    assert multiply(a, b) == multiply(abs(a), abs(b))
    assert multiply(a, b) == multiply(-abs(a), abs(b))
    assert multiply(a, b) == multiply(abs(a), -abs(b))
    assert multiply(a, b) == multiply(-abs(a), -abs(b))


@given(a=st.integers(min_value=-10000, max_value=10000),
       b=st.integers(min_value=-10000, max_value=10000))
def test_result_bounded_zero_to_81(a, b):
    r = multiply(a, b)
    assert 0 <= r <= 81


@given(a=st.integers(min_value=-10000, max_value=10000),
       b=st.integers(min_value=-10000, max_value=10000))
def test_commutativity(a, b):
    assert multiply(a, b) == multiply(b, a)


@given(a=st.integers(min_value=0, max_value=10000),
       b=st.integers(min_value=0, max_value=10000))
def test_last_digit_only_matters(a, b):
    # adding multiples of 10 must not change result; sign flip covered elsewhere
    assert multiply(a, b) == multiply(a + 10, b)
    assert multiply(a, b) == multiply(a, b + 100)
    assert multiply(a, b) == multiply(a + 1000, b + 1000)


@given(d1=st.integers(min_value=0, max_value=9),
       d2=st.integers(min_value=0, max_value=9),
       m1=st.integers(min_value=-500, max_value=500),
       m2=st.integers(min_value=-500, max_value=500))
def test_constructed_unit_digits(d1, d2, m1, m2):
    # build numbers with known unit digits, including negative ones
    # e.g. d1=7, m1=-3 -> -37 has unit digit 7
    a_pos = m1 * 10 + d1 if m1 >= 0 else m1 * 10 - d1
    b_pos = m2 * 10 + d2 if m2 >= 0 else m2 * 10 - d2
    assume(abs(a_pos) % 10 == d1)
    assume(abs(b_pos) % 10 == d2)
    assert multiply(a_pos, b_pos) == d1 * d2
